#!/usr/bin/env python3
"""M24.2d diagnostic v4 (not part of the pipeline). Runs ticker_noquit.resc to a point well
past the point where UART output stops (established by diag_ttc_trace3.py: last tick at
virtual ~30s of a run that has already gone 90 virtual seconds with TTC0.COUNT_VALUE still
demonstrably incrementing and zero further UART output), then probes the GIC directly to
find out whether the match condition is (a) never being generated by the TTC peripheral
itself (IRQ line never asserted -- GIC sees nothing pending), (b) asserted/pending at the GIC
but never taken by the CPU (a real interrupt-delivery/masking bug), or (c) something else.
Tries several monitor syntaxes for reading GIC state directly (both via `sysbus
ReadDoubleWord <addr> <cpu>` and via the `rpuGic` object's own methods), since the first
attempt (plain `sysbus ReadDoubleWord <gic-addr>`) failed with "Can't verify current CPU in
the given context" (GIC banked/multi-region registers need a CPU context on this bus)."""
import re
import socket
import subprocess
import sys
import time

ANSI_RE = re.compile(rb"\x1b\[[0-9;]*m")


class MonitorClient:
    def __init__(self, host, port, timeout=10.0):
        self.sock = socket.create_connection((host, port), timeout=timeout)
        self.sock.settimeout(timeout)

    def read_until_idle(self, idle_gap=0.3, overall_timeout=30.0):
        chunks = []
        deadline = time.monotonic() + overall_timeout
        self.sock.settimeout(idle_gap)
        while time.monotonic() < deadline:
            try:
                data = self.sock.recv(65536)
                if not data:
                    break
                chunks.append(data)
            except socket.timeout:
                if chunks:
                    break
                continue
        return b"".join(chunks)

    def read_until_marker(self, marker: bytes, poll_timeout=0.5, grace=0.05, overall_timeout=600.0):
        chunks = []
        buf = b""
        deadline = time.monotonic() + overall_timeout
        found_at = None
        while time.monotonic() < deadline:
            self.sock.settimeout(grace if found_at is not None else poll_timeout)
            try:
                data = self.sock.recv(65536)
                if not data:
                    break
                chunks.append(data)
                buf += data
            except socket.timeout:
                if found_at is not None:
                    break
                continue
            if found_at is None and marker in buf:
                found_at = time.monotonic()
        else:
            raise TimeoutError(f"marker {marker!r} not seen within {overall_timeout}s; buffer so far: {buf!r}")
        if found_at is None:
            raise TimeoutError(f"marker {marker!r} not seen within {overall_timeout}s; buffer so far: {buf!r}")
        return buf

    def send(self, line: str):
        self.sock.sendall((line + "\r\n").encode())

    def close(self):
        self.sock.close()


def clean(raw: bytes) -> str:
    return ANSI_RE.sub(b"", raw).decode(errors="replace").strip()


def try_cmd(client, cmd, label):
    client.send(cmd)
    out = clean(client.read_until_idle(idle_gap=0.3, overall_timeout=15.0))
    print(f"[{label}] {cmd!r} -> {out!r}", flush=True)
    return out


renode = "/Users/probe/code/AltaVista/third_party/renode/renode-1.16.1-osx-arm64/Renode.app/Contents/MacOS/renode"
rundir = "/Users/probe/code/AltaVista/third_party/rtems-container/run-renode"
resc = f"{rundir}/ticker_noquit.resc"
port = 3449

proc = subprocess.Popen([renode, "--disable-gui", "--hide-log", "-P", str(port)],
                         stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
try:
    deadline = time.monotonic() + 30
    client = None
    while time.monotonic() < deadline:
        try:
            client = MonitorClient("127.0.0.1", port)
            break
        except OSError:
            time.sleep(0.2)
    if client is None:
        print("FAIL: never connected")
        sys.exit(1)
    client.read_until_idle(idle_gap=0.3, overall_timeout=5.0)

    client.send(f"include @{resc}")
    client.read_until_marker(b"zynqmp-rpu-ticker) ", overall_timeout=60.0)
    print(">>> include done", flush=True)

    # Try several syntaxes for reading GIC state -- figure out which one Renode 1.16.1
    # actually accepts before trusting any value from it.
    print("\n--- probing GIC read syntaxes (before any RunFor) ---", flush=True)
    try_cmd(client, "sysbus ReadDoubleWord 0xf9000104 rpu0", "sysbus+cpu-name")
    try_cmd(client, "rpuGic ReadDoubleWord 0x104", "object-direct")
    try_cmd(client, "sysbus.cluster1.rpu0 sysbus ReadDoubleWord 0xf9000104", "prefixed")

    # Advance to nominal virtual 35s (established: last tick at ~30s nominal in the prior
    # 30-step run; this brackets a bit past it in one shot, cheap since counting continues
    # at near-real-time pace per the earlier measurement).
    print("\n--- RunFor 35s ---", flush=True)
    client.send('emulation RunFor "35"; currentTime')
    out = client.read_until_marker(b"Current real time:", overall_timeout=300.0)
    print(f"RunFor 35 reply: {clean(out)!r}", flush=True)

    print("\n--- state at nominal virtual ~35s ---", flush=True)
    try_cmd(client, "sysbus ReadDoubleWord 0xff110018", "TTC0.COUNT_VALUE")
    try_cmd(client, "sysbus ReadDoubleWord 0xff110030", "TTC0.MATCH_0")
    try_cmd(client, "sysbus ReadDoubleWord 0xff110054", "TTC0.ISR")
    try_cmd(client, "sysbus ReadDoubleWord 0xff110060", "TTC0.IER")
    try_cmd(client, "rpuGic ReadDoubleWord 0x104", "GIC.ISENABLER1(offset0x104)")
    try_cmd(client, "rpuGic ReadDoubleWord 0x204", "GIC.ISPENDR1(offset0x204)")
    try_cmd(client, "rpuGic ReadDoubleWord 0xc08", "GIC.ICFGR2(offset0xc08,edge/level)")
    try_cmd(client, "rpu0 PC", "rpu0.PC")
    try_cmd(client, "rpu0 IsHalted", "rpu0.IsHalted")

    with open(f"{rundir}/ticker_uart.log", "rb") as f:
        print(f"\nUART so far ({len(f.read())}B)", flush=True)

    client.send("quit")
    client.close()
finally:
    proc.poll()
    if proc.returncode is None:
        proc.kill()
        try:
            proc.wait(timeout=5)
        except Exception:
            pass
    print(f"renode final returncode: {proc.returncode}")
